def f(n: int, A: List[int], m: int, B: List[int]) -> str:
    i = j = 0
    result = []
    while i < n and j < m:
        if A[i] < B[j]:
            result.append(A[i])
            i += 1
        elif A[i] > B[j]:
            result.append(B[j])
            j += 1
        else:
            while i < n and A[i] == B[j]:
                result.append(A[i])
                i += 1
            result.append(B[j])
            j += 1
    while i < n:
        result.append(A[i])
        i += 1
    while j < m:
        result.append(B[j])
        j += 1
    return''.join(map(str, result))
